new file mode 100644
index 0000000..38d295c
--- /dev/null
+++ b/src/lib/geminiStore.js
@@ -0,0 +1,6 @@
+// Gemini changelog: new paid-tier projects store generateContent requests by
+// default (store=true). Opt out with store=false. SDK 1.7.0 has no typed
+// `store`, so send it via httpOptions.extraBody (merged into the request body).
+export const GEMINI_NO_STORE_CONFIG = {
+  httpOptions: { extraBody: { store: false } },
+};

